PRIMARY KEY (order_id, item_id)
COMMENT '粒度：订单商品；唯一键 order_id + item_id';
SELECT date(order_ts) AS stat_date, SUM(amount) AS gmv
FROM dwd_order_item GROUP BY 1;

WITH filtered AS (SELECT order_id, user_id, amount FROM dwd_order_item
  WHERE order_ts >= TIMESTAMP '2026-10-01 00:00:00'
)
SELECT user_id, COUNT(DISTINCT order_id) AS order_cnt, SUM(amount) AS gmv
FROM filtered GROUP BY user_id;
